import { countDecimals, precisionRound } from ".";

describe("math utils", () => {
  it("precisionRound", () => {
    expect(precisionRound(10.25156548)).toEqual(10.25);
    expect(precisionRound(10.25756548)).toEqual(10.26);
    expect(precisionRound(10.2156548, 1)).toEqual(10.2);
    expect(precisionRound(10.25756548, 1)).toEqual(10.3);
  });

  it("countDecimals", () => {
    expect(countDecimals(10)).toEqual(0);
    expect(countDecimals(10.2)).toEqual(1);
    expect(countDecimals(10.25)).toEqual(2);
    expect(countDecimals(10.123)).toEqual(3);
    expect(countDecimals(10.3333)).toEqual(4);
    expect(countDecimals(10.25156548)).toEqual(8);
    expect(countDecimals(0.00000000000000000001)).toEqual(20);
    expect(countDecimals(5e-25)).toEqual(25);
  });
});
